These utilities read the raw dump files (``*.pt``) referenced by a Polars
metadata DataFrame and turn them into simple, human-readable tables (rank
topology, input token ids / positions).
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Optional

import polars as pl

from sglang.srt.debug_utils.dump_loader import ValueWithMeta

_SGLANG_PARALLEL_INFO_KEY = "sglang_parallel_info"


def _render_polars_as_text(df: pl.DataFrame, *, title: Optional[str] = None) -> str:
    """Render a Polars DataFrame as an aligned text table.

    Includes ``title`` (when given) followed by the header (all column names)
    and one line per row. Empty DataFrames render without error.
    """
    lines: list[str] = []
    if title is not None:
        lines.append(title)

    columns: list[str] = list(df.columns)
    if not columns:
        return "\n".join(lines)

    data_rows: list[list[str]] = [
        [_format_cell(row[col]) for col in columns] for row in df.iter_rows(named=True)
    ]

    widths: dict[str, int] = {col: len(str(col)) for col in columns}
    for row in data_rows:
        for col, cell in zip(columns, row):
            widths[col] = max(widths[col], len(cell))

    header = " | ".join(str(col).ljust(widths[col]) for col in columns)
    separator = "-+-".join("-" * widths[col] for col in columns)
    lines.append(header)
    lines.append(separator)
    for row in data_rows:
        lines.append(
            " | ".join(cell.ljust(widths[col]) for col, cell in zip(columns, row))
        )

    return "\n".join(lines)


def _format_cell(value: Any) -> str:
    if value is None:
        return ""
    return str(value)


def _extract_parallel_info(row_data: dict[str, Any], info: dict[str, Any]) -> None:
    """Write ``{rank}/{size}`` parallel entries from ``info`` into ``row_data``.

    For every ``<base>_rank`` key in ``info`` that has a matching ``<base>_size``
    key, sets ``row_data[base] = "{rank}/{size}"``. Does nothing when ``info`` is
    empty or contains an ``"error"`` key. ``_rank`` keys without a matching
    ``_size`` are skipped.
    """
    if not info or "error" in info:
        return

    for key in info:
        if not key.endswith("_rank"):
            continue
        base = key[: -len("_rank")]
        size_key = f"{base}_size"
        if size_key not in info:
            continue
        row_data[base] = f"{info[key]}/{info[size_key]}"


def _collect_rank_info(
    df: pl.DataFrame, dump_dir: Path
) -> Optional[list[dict[str, Any]]]:
    """Collect per-rank parallel topology from the ``input_ids`` dump files.

    Returns ``None`` when no rows named ``"input_ids"`` exist. Otherwise returns
    a list with one dict per unique rank, each containing ``"rank"`` and any
    parallel dimension entries (e.g. ``"tp": "0/2"``) read from
    ``sglang_parallel_info`` in the file metadata.
    """
    matching = df.filter(pl.col("name") == "input_ids")
    if matching.height == 0:
        return None

    dump_dir = Path(dump_dir)
    result: list[dict[str, Any]] = []
    seen_ranks: set[Any] = set()
    for row in matching.iter_rows(named=True):
        rank = row.get("rank")
        if rank in seen_ranks:
            continue
        seen_ranks.add(rank)

        loaded = ValueWithMeta.load(dump_dir / row["filename"])
        info = loaded.meta.get(_SGLANG_PARALLEL_INFO_KEY) or {}

        row_data: dict[str, Any] = {"rank": rank}
        _extract_parallel_info(row_data, info)
        result.append(row_data)

    return result


